import csv
import io
import unicodedata

from csvledger.errors import LedgerError


def _raise_limit():
    limit = 2**31 - 1
    while True:
        try:
            csv.field_size_limit(limit)
            return
        except OverflowError:
            limit //= 2


_raise_limit()


def clean(text):
    return "".join(" " if unicodedata.category(c) == "Cc" else c for c in text)


sanitize = clean


def read_records(path, required, exit_code):
    def err(msg):
        return LedgerError(msg, exit_code)

    try:
        with open(path, "rb") as f:
            data = f.read()
        text = data.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise err(f"{path}: not valid UTF-8")
    except OSError:
        raise err(f"{path}: cannot read file")

    reader = csv.reader(io.StringIO(text, newline=""))
    try:
        header = next(reader, None)
        if header is None:
            raise err(f"{path}: missing header")
        names = [h.strip().lower() for h in header]
        seen = set()
        for n in names:
            if n in seen:
                raise err(f"{path}: duplicate column '{clean(n)}'")
            seen.add(n)
        for r in required:
            if r not in seen:
                raise err(f"{path}: missing column '{r}'")
        for row in reader:
            if not row:
                continue
            if len(row) != len(names):
                raise err(
                    f"{path}:{reader.line_num}: expected {len(names)} fields, got {len(row)}"
                )
            yield reader.line_num, dict(zip(names, row))
    except csv.Error:
        raise err(f"{path}:{reader.line_num}: malformed CSV")

import decimal
import re
from decimal import Decimal, ROUND_HALF_UP

MONEY_CONTEXT = decimal.Context(
    prec=decimal.MAX_PREC, Emax=decimal.MAX_EMAX, Emin=decimal.MIN_EMIN
)

AMOUNT_RE = re.compile(r"-?[0-9]+(\.[0-9]+)?")

_CENT = Decimal("0.01")


def parse_amount(text):
    if not AMOUNT_RE.fullmatch(text):
        raise ValueError(f"invalid amount {text!r}")
    return MONEY_CONTEXT.create_decimal(text)


def fmt_money(value):
    q = value.quantize(_CENT, ROUND_HALF_UP, context=MONEY_CONTEXT)
    if q == 0:
        return "0.00"
    return format(q, "f")

import json

from csvledger.csvio import clean as sanitize


def render_table(headers, aligns, rows):
    rows = [[sanitize(c) for c in row] for row in rows]
    widths = [len(h) for h in headers]
    for row in rows:
        for i, c in enumerate(row):
            widths[i] = max(widths[i], len(c))

    def line(cells):
        out = "  ".join(
            c.rjust(w) if a == "r" else c.ljust(w)
            for c, w, a in zip(cells, widths, aligns)
        )
        return out.rstrip(" ")

    lines = [line(headers), line(["-" * w for w in widths])]
    lines.extend(line(r) for r in rows)
    return "\n".join(lines) + "\n"


def render_json(obj):
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"

import re
from dataclasses import dataclass
from typing import Any

from csvledger.csvio import clean, read_records
from csvledger.errors import LedgerError

UNCATEGORIZED = "Uncategorized"
_PRIORITY = re.compile(r"-?[0-9]+")


@dataclass(frozen=True)
class Rule:
    category: str
    type: str
    pattern: str
    priority: int
    index: int
    compiled: Any = None


def load_rules(path):
    rules = []
    for line, row in read_records(path, ("category", "type", "pattern", "priority"), 4):

        def fail(msg):
            return LedgerError(f"{path}:{line}: {msg}", 4)

        category = row["category"].strip()
        rtype = row["type"].strip()
        pattern = row["pattern"].strip()
        prio = row["priority"].strip()
        if not category:
            raise fail("empty category")
        if rtype not in ("contains", "regex"):
            raise fail(f"invalid type '{clean(rtype)}'")
        if not pattern:
            raise fail("empty pattern")
        priority = None
        if _PRIORITY.fullmatch(prio):
            try:
                priority = int(prio)
            except ValueError:
                pass
        if priority is None:
            raise fail(f"invalid priority '{clean(prio)}'")
        compiled = None
        if rtype == "regex":
            try:
                compiled = re.compile(pattern, re.IGNORECASE)
            except (re.error, OverflowError, RecursionError):
                raise fail(f"invalid regex '{clean(pattern)}'")
        rules.append(Rule(category, rtype, pattern, priority, len(rules), compiled))
    return rules


def categorize(rules, description):
    folded = description.casefold()
    best = None
    for r in rules:
        if r.type == "contains":
            hit = r.pattern.casefold() in folded
        else:
            hit = r.compiled.search(description) is not None
        if hit and (best is None or r.priority > best.priority):
            best = r
    return best.category if best else UNCATEGORIZED

import datetime
import re
from dataclasses import dataclass
from decimal import Decimal

from csvledger.csvio import clean, read_records
from csvledger.errors import EXIT_TRANSACTIONS, LedgerError
from csvledger.money import parse_amount

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


@dataclass(frozen=True)
class Transaction:
    date: str
    description: str
    amount: Decimal


def _valid_date(value):
    if not _DATE_RE.fullmatch(value):
        return False
    try:
        datetime.date(int(value[:4]), int(value[5:7]), int(value[8:]))
    except ValueError:
