def load_transactions(path):
    result = []
    for line, row in read_records(path, ("date", "description", "amount"), EXIT_TRANSACTIONS):
        date = row["date"].strip()
        if not _valid_date(date):
            raise LedgerError(f"{path}:{line}: invalid date '{clean(date)}'", EXIT_TRANSACTIONS)
        raw = row["amount"].strip()
        try:
            amount = parse_amount(raw)
        except ValueError:
            raise LedgerError(f"{path}:{line}: invalid amount '{clean(raw)}'", EXIT_TRANSACTIONS)
        result.append(Transaction(date, row["description"].strip(), amount))
