from dataclasses import dataclass, field
from decimal import Decimal

from csvledger.money import MONEY_CONTEXT

_ZERO = Decimal(0)


@dataclass
class Totals:
    count: int = 0
    income: Decimal = _ZERO
    expenses: Decimal = _ZERO

    @property
    def net(self):
        return MONEY_CONTEXT.add(self.income, self.expenses)

    def add(self, amount):
        self.count += 1
        if amount > 0:
            self.income = MONEY_CONTEXT.add(self.income, amount)
        elif amount < 0:
            self.expenses = MONEY_CONTEXT.add(self.expenses, amount)


@dataclass
class MonthTotals(Totals):
    categories: list = field(default_factory=list)  # [(category, Totals)]


def aggregate(categorized):
    cells = {}
    for tx, category in categorized:
        cells.setdefault((tx.date[:7], category), Totals()).add(tx.amount)
    months = {}
    for (month, category) in sorted(cells):
        t = cells[(month, category)]
        m = months.setdefault(month, MonthTotals())
        m.count += t.count
        m.income = MONEY_CONTEXT.add(m.income, t.income)
        m.expenses = MONEY_CONTEXT.add(m.expenses, t.expenses)
        m.categories.append((category, t))
    return [(month, months[month]) for month in sorted(months)]

