import argparse
import re
import sys

from csvledger.aggregate import aggregate
from csvledger.dedupe import dedupe, filter_month
from csvledger.errors import EXIT_INTERNAL, EXIT_OK, LedgerError
from csvledger.formatting import (
    categorize_json,
    categorize_table,
    report_json,
    report_table,
)
from csvledger.rules import categorize, load_rules
from csvledger.transactions import load_transactions

_MONTH = re.compile(r"[0-9]{4}-(0[1-9]|1[0-2])")


def _month(value):
    if not _MONTH.fullmatch(value):
        raise argparse.ArgumentTypeError(f"invalid month '{value}' (expected YYYY-MM)")
    return value


def build_parser():
    parser = argparse.ArgumentParser(prog="csvledger", allow_abbrev=False)
    sub = parser.add_subparsers(dest="command", required=True)
    for name, helptext in (
        ("report", "monthly totals per category"),
        ("categorize", "list transactions with their category"),
    ):
        p = sub.add_parser(name, help=helptext, allow_abbrev=False)
        p.add_argument("--rules", metavar="PATH")
        p.add_argument("--format", choices=("table", "json"), default="table")
        p.add_argument("--month", type=_month)
        p.add_argument("FILE", nargs="+")
    return parser


def _configure_streams():
    for stream, kwargs in (
        (sys.stdout, {"encoding": "utf-8", "newline": "\n"}),
        (sys.stderr, {"encoding": "utf-8", "newline": "\n", "errors": "backslashreplace"}),
    ):
        if hasattr(stream, "reconfigure"):
            try:
                stream.reconfigure(**kwargs)
            except Exception:
                pass


def _run(args):
    rules = load_rules(args.rules) if args.rules else []
    transactions = []
    for path in args.FILE:
        transactions.extend(load_transactions(path))
    transactions, skipped = dedupe(transactions)
    transactions = filter_month(transactions, args.month)
    categorized = [(t, categorize(rules, t.description)) for t in transactions]
    as_json = args.format == "json"
    if args.command == "report":
        months = aggregate(categorized)
        text = report_json(months) if as_json else report_table(months)
    else:
        text = categorize_json(categorized) if as_json else categorize_table(categorized)
    out = getattr(sys.stdout, "buffer", None)
    if out is not None:
        out.write(text.encode("utf-8"))
        out.flush()
    else:
        sys.stdout.write(text)
        sys.stdout.flush()
    if skipped > 0:
        sys.stderr.write(f"csvledger: warning: skipped {skipped} duplicate row(s)\n")
        sys.stderr.flush()
    return EXIT_OK


def main(argv=None) -> int:
    _configure_streams()
    args = build_parser().parse_args(argv)
    try:
        return _run(args)
    except LedgerError as e:
        sys.stderr.write(f"csvledger: error: {e.message}\n")
        return e.exit_code
    except Exception as e:
        sys.stderr.write(f"csvledger: error: internal error: {type(e).__name__}\n")
        return EXIT_INTERNAL

